package com.sih.portal.service; import com.sih.portal.entity.*; import com.sih.portal.repo.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; import org.springframework.http.*; @Service @Transactional public class PortalService{final Appointments a;final Teleconsultations t;public PortalService(Appointments a,Teleconsultations t){this.a=a;this.t=t;}String x(){return TenantContext.requireCurrentTenant();}public List<Appointment>appointments(){return a.findByTenantIdOrderByScheduledAtAsc(x());}public Appointment book(Appointment q){q.setId(null);return a.save(q);}public Appointment confirm(Long i){var q=a.findByIdAndTenantId(i,x()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!"REQUESTED".equals(q.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);q.setStatus("CONFIRMED");return q;}public List<Teleconsultation>tele(){return t.findByTenantIdOrderByScheduledAtAsc(x());}public Teleconsultation create(Teleconsultation q){q.setId(null);q.setStatus("SCHEDULED");return t.save(q);}public Teleconsultation start(Long i){var q=t.findByIdAndTenantId(i,x()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!"SCHEDULED".equals(q.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);q.setStatus("STARTED");return q;}public Teleconsultation complete(Long i){var q=t.findByIdAndTenantId(i,x()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!"STARTED".equals(q.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);q.setStatus("COMPLETED");return q;}}